    destruct (stk_split asegs _ (sh a) (sh a + 512) (sh a + msz / 8) SHK ltac:(hci; lia)) as [SH1 SHR]. clear SHK.
    destruct (stk_split asegs _ (sh a + 512) (sh a + 512 + size8) (sh a + msz / 8) SHR ltac:(hci; lia)) as [SHM SH3]. clear SHR.
